.sb-wf--simple { min-width: 1280px; }
.sb-wf-row { display: flex; gap: 8px; align-items: center; }
.sb-wf-title { font-size: 12px; font-weight: 700; color: #334155; margin: 0 0 8px; }
.sb-wf-caption { font-size: 10px; color: #64748b; margin: 4px 0 0; }
.sb-wf-btn--sm { padding: 4px 10px; font-size: 9px; border-radius: 10px; }
.sb-wf-text--desc { font-size: 10px; color: #64748b; line-height: 1.6; margin: 0 0 10px; }
.sb-wf--simple .sb-wf-nav-panel { width: 200px; display: flex; flex-direction: column; min-height: 720px; }
.sb-wf--simple .sb-wf-nav-scroll { flex: 1; display: flex; flex-direction: column; }
.sb-wf-simple-main { flex: 1; display: flex; flex-direction: column; min-width: 0; background: #f8fafc; }
.sb-wf-simple-topbar { display: flex; align-items: center; gap: 12px; padding: 10px 20px; border-bottom: 1px solid #e2e8f0; background: #fff; }
.sb-wf-breadcrumb { font-size: 11px; color: #64748b; flex-shrink: 0; white-space: nowrap; }
.sb-wf-breadcrumb strong { color: #334155; font-weight: 600; }
.sb-wf-simple-topbar .sb-wf-search { flex: 1; max-width: 420px; margin: 0 auto; display: flex; align-items: center; justify-content: space-between; padding: 8px 14px; border: 2px dashed #cbd5e1; border-radius: 999px; background: #fafbfc; font-size: 11px; color: #94a3b8; }
.sb-wf-search-kbd { font-size: 9px; padding: 2px 6px; border: 1px solid #e2e8f0; border-radius: 4px; background: #fff; color: #94a3b8; }
.sb-wf-simple-topbar-actions { display: flex; align-items: center; gap: 10px; margin-left: auto; flex-shrink: 0; }
.sb-wf-simple-body { flex: 1; display: flex; gap: 16px; padding: 16px 20px; align-items: flex-start; }
.sb-wf-simple-center { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 14px; }
.sb-wf-simple-side { flex: 0 0 240px; display: flex; flex-direction: column; gap: 12px; }
.sb-wf-simple-hero { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; padding: 16px 18px; border: 1px dashed #cbd5e1; border-radius: 12px; background: #fff; }
.sb-wf-simple-hero-text { flex: 1; min-width: 0; }
.sb-wf-simple-hero-text .sb-wf-text--h1 { font-size: 18px; margin-bottom: 6px; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.sb-wf-simple-badge { display: inline-flex; padding: 3px 8px; border-radius: 999px; background: #dcfce7; border: 1px solid #86efac; font-size: 9px; font-weight: 700; color: #15803d; }
.sb-wf-simple-hero-visual { flex: 0 0 100px; min-height: 80px; background: #f1f5f9; border: 2px dashed #cbd5e1; border-radius: 10px; display: flex; flex-direction: column; align-items: center; justify-content: center; font-size: 9px; color: #94a3b8; text-align: center; padding: 8px; }
.sb-wf-simple-hero-visual::before { content: '✕ VISUAL'; font-size: 10px; font-weight: 700; color: #64748b; margin-bottom: 4px; }
.sb-wf-prompt-box { border: 2px dashed #c4b5fd; border-radius: 12px; background: #faf5ff; padding: 18px 16px; }
.sb-wf-prompt-box .sb-wf-title { font-size: 13px; margin-bottom: 4px; }
.sb-wf-prompt-textarea { min-height: 100px; border: 2px dashed #cbd5e1; border-radius: 10px; background: #fff; padding: 12px 14px; font-size: 11px; color: #94a3b8; line-height: 1.5; margin: 10px 0 8px; }
.sb-wf-prompt-foot { display: flex; justify-content: space-between; align-items: center; }
.sb-wf-prompt-count { font-size: 10px; color: #94a3b8; }
.sb-wf-btn--send { width: 36px; height: 36px; border-radius: 10px; padding: 0; background: #6366f1; border-color: #6366f1; color: #fff; font-size: 14px; }
.sb-wf-alt-divider { text-align: center; font-size: 10px; color: #94a3b8; margin: 4px 0 10px; position: relative; }
.sb-wf-alt-divider::before, .sb-wf-alt-divider::after { content: ''; position: absolute; top: 50%; width: 42%; height: 1px; background: #e2e8f0; }
.sb-wf-alt-divider::before { left: 0; }
.sb-wf-alt-divider::after { right: 0; }
.sb-wf-alt-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
.sb-wf-alt-card { border: 1px dashed #cbd5e1; border-radius: 10px; padding: 12px 10px; background: #fff; min-height: 88px; }
.sb-wf-alt-card .sb-wf-block--icon { width: 28px; height: 28px; margin-bottom: 8px; font-size: 12px; }
.sb-wf-alt-card .sb-wf-text { font-size: 10px; font-weight: 700; color: #334155; margin-bottom: 4px; }
.sb-wf-alt-card .sb-wf-caption { font-size: 9px; color: #64748b; line-height: 1.35; margin: 0; }
.sb-wf-tips-banner { border: 1px dashed #c4b5fd; border-radius: 10px; background: #f5f3ff; padding: 12px 14px; }
.sb-wf-tips-banner .sb-wf-text { font-size: 10px; color: #64748b; margin-bottom: 8px; }
.sb-wf-tag-row { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
.sb-wf-tag { padding: 4px 10px; border: 1px solid #cbd5e1; border-radius: 999px; font-size: 9px; color: #64748b; background: #fff; }
.sb-wf-tag-link { font-size: 9px; color: #6366f1; font-weight: 600; margin-left: auto; }
.sb-wf-side-card { border: 1px dashed #cbd5e1; border-radius: 10px; padding: 12px; background: #fff; }
.sb-wf-side-card-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; }
.sb-wf-side-card-head .sb-wf-title { margin: 0; font-size: 11px; }
.sb-wf-side-link { font-size: 9px; color: #6366f1; font-weight: 600; }
.sb-wf-history-list { list-style: none; margin: 0; padding: 0; }
.sb-wf-history-item { display: flex; gap: 8px; padding: 8px 0; border-bottom: 1px dotted #e2e8f0; align-items: flex-start; }
.sb-wf-history-item:last-child { border-bottom: none; }
.sb-wf-history-thumb { width: 40px; height: 40px; flex-shrink: 0; background: #f1f5f9; border: 2px dashed #cbd5e1; border-radius: 6px; display: flex; align-items: center; justify-content: center; font-size: 8px; color: #94a3b8; }
.sb-wf-history-thumb::before { content: '✕ THUMB'; }
.sb-wf-history-meta .sb-wf-text { font-size: 10px; font-weight: 600; margin-bottom: 2px; }
.sb-wf-history-meta .sb-wf-caption { font-size: 9px; margin: 0; line-height: 1.35; }
.sb-wf-tip-list { list-style: none; margin: 0; padding: 0; }
.sb-wf-tip-list li { display: flex; gap: 8px; padding: 7px 0; font-size: 9px; color: #64748b; line-height: 1.4; border-bottom: 1px dotted #e2e8f0; }
.sb-wf-tip-list li:last-child { border-bottom: none; }
.sb-wf-tip-list .sb-wf-block--icon { width: 20px; height: 20px; font-size: 9px; flex-shrink: 0; }
.sb-wf-points-card { margin-top: auto; padding: 12px; border: 1px dashed #fcd34d; border-radius: 10px; background: #fffbeb; }
.sb-wf-points-card .sb-wf-subtitle { margin: 0 0 4px; font-size: 9px; text-transform: none; color: #92400e; }
.sb-wf-points-card .sb-wf-text { font-size: 14px; font-weight: 800; color: #b45309; }
.sb-wf-stepper { display: flex; gap: 0; padding: 12px 20px; border-top: 1px solid #e2e8f0; background: #fff; }
.sb-wf-stepper-item { flex: 1; display: flex; flex-direction: column; align-items: center; text-align: center; position: relative; padding: 0 8px; }
.sb-wf-stepper-item:not(:last-child)::after { content: '→'; position: absolute; right: -6px; top: 8px; font-size: 12px; color: #cbd5e1; }
.sb-wf-stepper-num { width: 24px; height: 24px; border-radius: 50%; background: #e2e8f0; border: 2px solid #cbd5e1; display: flex; align-items: center; justify-content: center; font-size: 10px; font-weight: 700; color: #64748b; margin-bottom: 4px; }
.sb-wf-stepper-item.is-active .sb-wf-stepper-num { background: #6366f1; border-color: #6366f1; color: #fff; }
.sb-wf-stepper-label { font-size: 10px; font-weight: 700; color: #334155; margin-bottom: 2px; }
.sb-wf-stepper-desc { font-size: 9px; color: #94a3b8; line-height: 1.3; }
.sb-wf-badge { display: inline-block; padding: 1px 5px; background: #fef3c7; border: 1px solid #fcd34d; border-radius: 999px; font-size: 8px; font-weight: 700; color: #b45309; }
.sb-wf-badge--dot { width: 14px; height: 14px; background: #fca5a5; border: 1px solid #f87171; border-radius: 50%; font-size: 8px; color: #fff; display: flex; align-items: center; justify-content: center; padding: 0; }
.sb-wf-block--avatar { width: 28px; height: 28px; border-radius: 50%; background: #cbd5e1; border: 2px solid #fff; }
.sb-wf-btn--primary { background: #6366f1; border-color: #6366f1; color: #fff; }
.sb-wf-nav-bottom-item { margin-top: auto; }
